-- MediCrew production readiness: secure document uploads, payment ledger,
-- push-token registration, international metadata and email-verification guards.
alter table public.profiles add column if not exists country_code text, add column if not exists preferred_language text default 'en', add column if not exists currency_code text default 'EUR';
alter table public.companies add column if not exists country_code text, add column if not exists currency_code text default 'EUR';
alter table public.professionals add column if not exists country_code text, add column if not exists currency_code text default 'EUR';
alter table public.missions add column if not exists country_code text, add column if not exists currency_code text default 'EUR', add column if not exists platform_fee_cents integer not null default 10000;
alter table public.professional_documents add column if not exists storage_path text, add column if not exists original_name text, add column if not exists mime_type text, add column if not exists size_bytes bigint, add column if not exists uploaded_at timestamptz;
create index if not exists professional_documents_storage_path_idx on public.professional_documents(storage_path) where storage_path is not null;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('professional-documents','professional-documents',false,10485760,array['application/pdf','image/jpeg','image/png','image/webp']::text[]) on conflict(id) do update set public=false,file_size_limit=10485760,allowed_mime_types=array['application/pdf','image/jpeg','image/png','image/webp']::text[];
drop policy if exists professional_documents_storage_insert on storage.objects;
drop policy if exists professional_documents_storage_select on storage.objects;
drop policy if exists professional_documents_storage_update on storage.objects;
drop policy if exists professional_documents_storage_delete on storage.objects;
create policy professional_documents_storage_insert on storage.objects for insert to authenticated with check(bucket_id='professional-documents' and(storage.foldername(name))[1]=(select auth.uid())::text);
create policy professional_documents_storage_select on storage.objects for select to authenticated using(bucket_id='professional-documents' and((storage.foldername(name))[1]=(select auth.uid())::text or exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin')));
create policy professional_documents_storage_update on storage.objects for update to authenticated using(bucket_id='professional-documents' and(storage.foldername(name))[1]=(select auth.uid())::text) with check(bucket_id='professional-documents' and(storage.foldername(name))[1]=(select auth.uid())::text);
create policy professional_documents_storage_delete on storage.objects for delete to authenticated using(bucket_id='professional-documents' and((storage.foldername(name))[1]=(select auth.uid())::text or exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin')));
create table if not exists public.push_tokens(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.profiles(id) on delete cascade,expo_push_token text not null unique,platform text not null check(platform in('ios','android','web')),device_id text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_seen_at timestamptz not null default now());
create index if not exists push_tokens_profile_idx on public.push_tokens(profile_id);
alter table public.push_tokens enable row level security;
drop policy if exists push_tokens_owner_select on public.push_tokens;
drop policy if exists push_tokens_owner_insert on public.push_tokens;
drop policy if exists push_tokens_owner_update on public.push_tokens;
drop policy if exists push_tokens_owner_delete on public.push_tokens;
create policy push_tokens_owner_select on public.push_tokens for select to authenticated using(profile_id=(select auth.uid()));
create policy push_tokens_owner_insert on public.push_tokens for insert to authenticated with check(profile_id=(select auth.uid()));
create policy push_tokens_owner_update on public.push_tokens for update to authenticated using(profile_id=(select auth.uid())) with check(profile_id=(select auth.uid()));
create policy push_tokens_owner_delete on public.push_tokens for delete to authenticated using(profile_id=(select auth.uid()));
create trigger push_tokens_updated_at before update on public.push_tokens for each row execute procedure public.set_updated_at();
create table if not exists public.mission_payments(id uuid primary key default gen_random_uuid(),mission_id uuid not null unique references public.missions(id) on delete cascade,company_id uuid not null references public.companies(id) on delete cascade,amount_cents integer not null check(amount_cents>0),currency_code text not null default 'EUR',status text not null default 'pending' check(status in('pending','processing','paid','failed','refunded','cancelled')),stripe_payment_intent_id text unique,stripe_customer_id text,paid_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists mission_payments_company_idx on public.mission_payments(company_id,created_at desc);
create index if not exists mission_payments_status_idx on public.mission_payments(status);
alter table public.mission_payments enable row level security;
drop policy if exists mission_payments_company_select on public.mission_payments;
drop policy if exists mission_payments_admin_select on public.mission_payments;
create policy mission_payments_company_select on public.mission_payments for select to authenticated using(company_id=(select auth.uid()));
create policy mission_payments_admin_select on public.mission_payments for select to authenticated using(exists(select 1 from public.profiles where id=(select auth.uid()) and role='admin'));
create trigger mission_payments_updated_at before update on public.mission_payments for each row execute procedure public.set_updated_at();
create or replace function public.create_mission_payment_after_completion() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.status='completed' and old.status is distinct from 'completed' then insert into public.mission_payments(mission_id,company_id,amount_cents,currency_code) values(new.id,new.company_id,greatest(new.platform_fee_cents,1),coalesce(new.currency_code,'EUR')) on conflict(mission_id) do nothing; end if; return new; end; $$;
drop trigger if exists mission_payment_after_completion on public.missions;
create trigger mission_payment_after_completion after update on public.missions for each row execute function public.create_mission_payment_after_completion();
create or replace function public.require_confirmed_email() returns trigger language plpgsql security definer set search_path=public,auth as $$ begin if auth.uid() is not null and exists(select 1 from auth.users u where u.id=auth.uid() and u.email_confirmed_at is null) then raise exception 'Email verification required before using the MediCrew marketplace'; end if; return new; end; $$;
drop trigger if exists require_confirmed_email_missions on public.missions;
create trigger require_confirmed_email_missions before insert or update on public.missions for each row execute function public.require_confirmed_email();
drop trigger if exists require_confirmed_email_applications on public.mission_applications;
create trigger require_confirmed_email_applications before insert or update on public.mission_applications for each row execute function public.require_confirmed_email();
create or replace function public.guard_match_email_verification() returns trigger language plpgsql security definer set search_path=public,auth as $$ begin if new.eligible and exists(select 1 from auth.users u where u.id=new.professional_id and u.email_confirmed_at is null) then new.eligible:=false;new.reasons:=array_append(coalesce(new.reasons,'{}'::text[]),'Email verification required');end if;return new;end; $$;
drop trigger if exists mission_match_email_guard on public.mission_matches;
create trigger mission_match_email_guard before insert or update on public.mission_matches for each row execute function public.guard_match_email_verification();
create or replace function public.refresh_expired_professional_documents() returns integer language plpgsql security definer set search_path=public as $$ declare changed integer;begin update public.professional_documents set status='expired',updated_at=now() where expires_at is not null and expires_at<current_date and status in('pending','verified');get diagnostics changed=row_count;return changed;end; $$;
revoke all on function public.refresh_expired_professional_documents() from public;grant execute on function public.refresh_expired_professional_documents() to authenticated;
create or replace function public.upsert_my_availability_slot(p_slot_id uuid default null,p_starts_at timestamptz default null,p_ends_at timestamptz default null,p_start_location text default null,p_max_notice_hours numeric default 3,p_international boolean default false,p_transport_types text[] default '{}') returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;if not exists(select 1 from public.professionals where id=auth.uid() and verification_status<>'suspended') then raise exception 'Professional account unavailable';end if;if p_starts_at is null or p_ends_at is null or p_ends_at<=p_starts_at then raise exception 'Availability window is invalid';end if;if p_starts_at<=now() then raise exception 'Availability must be in the future';end if;if p_max_notice_hours is not null and p_max_notice_hours<0 then raise exception 'Notice cannot be negative';end if;if p_slot_id is null then insert into public.professional_availability(professional_id,starts_at,ends_at,start_location,max_notice_hours,international,transport_types) values(auth.uid(),p_starts_at,p_ends_at,nullif(trim(p_start_location),''),greatest(coalesce(p_max_notice_hours,0),0),coalesce(p_international,false),coalesce(p_transport_types,'{}')) returning id into v_id;else update public.professional_availability set starts_at=p_starts_at,ends_at=p_ends_at,start_location=nullif(trim(p_start_location),''),max_notice_hours=greatest(coalesce(p_max_notice_hours,0),0),international=coalesce(p_international,false),transport_types=coalesce(p_transport_types,'{}') where id=p_slot_id and professional_id=auth.uid() returning id into v_id;if v_id is null then raise exception 'Availability slot not found';end if;end if;return v_id;end; $$;
revoke all on function public.upsert_my_availability_slot(uuid,timestamptz,timestamptz,text,numeric,boolean,text[]) from public;grant execute on function public.upsert_my_availability_slot(uuid,timestamptz,timestamptz,text,numeric,boolean,text[]) to authenticated;
create or replace function public.delete_my_availability_slot(p_slot_id uuid) returns void language plpgsql security definer set search_path=public as $$ begin delete from public.professional_availability where id=p_slot_id and professional_id=auth.uid();end; $$;
revoke all on function public.delete_my_availability_slot(uuid) from public;grant execute on function public.delete_my_availability_slot(uuid) to authenticated;
create or replace function public.admin_verification_queue_v2() returns jsonb language plpgsql security definer set search_path=public as $$ declare result jsonb;begin if not exists(select 1 from public.profiles where id=auth.uid() and role='admin') then raise exception 'Admin access required';end if;select jsonb_build_object('documents',coalesce((select jsonb_agg(row_to_json(x) order by x.created_at desc) from(select d.id,d.professional_id,d.document_type,d.title,d.reference,d.expires_at,d.status,d.rejection_reason,d.created_at,d.storage_path,d.original_name,d.mime_type,d.size_bytes,d.uploaded_at,p.first_name,p.last_name,pr.professional_type,pr.specialty,pr.rpps_number from public.professional_documents d join public.profiles p on p.id=d.professional_id join public.professionals pr on pr.id=d.professional_id where d.status='pending' or(d.expires_at is not null and d.expires_at<current_date and d.status='verified'))x),'[]'::jsonb),'certifications',coalesce((select jsonb_agg(row_to_json(y) order by y.created_at desc) from(select c.id,c.professional_id,c.name,c.issuer,c.issued_at,c.expires_at,c.status,c.created_at,p.first_name,p.last_name from public.professional_certifications c join public.profiles p on p.id=c.professional_id where c.status='pending' or(c.expires_at is not null and c.expires_at<current_date and c.status='verified'))y),'[]'::jsonb)) into result;return result;end; $$;
revoke all on function public.admin_verification_queue_v2() from public;grant execute on function public.admin_verification_queue_v2() to authenticated;

